def trigger_emotional_intervention(user_id, real_time_metrics, historical_data):
    """
    Decide which emotional intervention to deploy based on real-time metrics and history.

    real_time_metrics: dict with keys 'typing_speed', 'voice_pitch', 'sentiment_score'
    historical_data: dict with keys 'recent_interventions', 'engagement_trend', 'forgetting_curve'

    Returns: dict with 'intervention_type' and 'payload' (message, action, or delay)
    """
    # Extract metrics
    typing_speed = real_time_metrics.get('typing_speed', 0.0)        # chars per second
    voice_pitch = real_time_metrics.get('voice_pitch', 0.0)          # normalized 0..1
    sentiment_score = real_time_metrics.get('sentiment_score', 0.0)  # -1 (negative) to +1 (positive)

    # --- 1. Detect emotional state ---
    if sentiment_score < -0.3:
        state = "frustrated"
    elif sentiment_score < 0.2 and typing_speed < 1.0:
        state = "fatigued"
    elif sentiment_score > 0.5 and typing_speed > 4.0:
        state = "flowing"
    else:
        state = "neutral"

    # --- 2. Check recent intervention history (avoid over‑intervention) ---
    recent = historical_data.get('recent_interventions', [])
    last_intervention_type = recent[-1]['type'] if recent else None
    time_since_last = recent[-1]['time'] if recent else float('inf')

    # --- 3. Decide intervention based on state + spaced recall opportunity ---
    intervention = {
        "user_id": user_id,
        "timestamp": time.now()
    }

    if state == "frustrated":
        # Emotional anchoring: soothing / morale boost
        if time_since_last < 60:  # already intervened within last minute
            intervention["type"] = "do_nothing"
            intervention["reason"] = "recent_intervention"
        else:
            intervention["type"] = "emotional_support"
            intervention["payload"] = {
                "message": "This concept **is** tricky – here's a different analogy...",
                "action": "present_alternative_explanation",
                "delay_seconds": 2   # brief pause before showing
            }

    elif state == "fatigued":
        # Cognitive offloading: offer a break or micro‑activity
        if typing_speed < 0.5 and sentiment_score < 0:
            intervention["type"] = "break_suggestion"
            intervention["payload"] = {
                "message": "You've been working hard. How about a 90‑second brain break?",
                "action": "offer_micro_break",
                "duration": 90
            }
        else:
            intervention["type"] = "gentle_redirect"
            intervention["payload"] = {
                "message": "Let's try a quick, easier review question to reset.",
                "action": "switch_to_review"
            }

    elif state == "flowing":
        # Just‑in‑time curiosity trigger + spaced recall anchor
        # Use historical forgetting curve to pick a concept due for review
        due_concept = find_due_for_review(historical_data.get('forgetting_curve', {}))
        if due_concept and not already_shown_today(due_concept):
            intervention["type"] = "positive_reinforcement_spaced_recall"
            intervention["payload"] = {
                "message": f"Great momentum! Quick check: remember how {due_concept} works?",
                "action": "interleave_review",
                "concept": due_concept
            }
        else:
            intervention["type"] = "affirmation"
            intervention["payload"] = {
                "message": "You're really getting this – keep going!",
                "action": "no_interruption"
            }

    else:  # neutral
        # Default: subtle emotional anchoring – mirror pace or pitch
        if voice_pitch > 0.7 and typing_speed > 3.0:
            intervention["type"] = "mirrored_enthusiasm"
            intervention["payload"] = {
                "message": "I can tell you're engaging – here's something that builds on that energy.",
                "action": "offer_slightly_harder_problem"
            }
        else:
            intervention["type"] = "calm_presence"
            intervention["payload"] = {
                "message": None,  # no visible message
                "action": "continue_current_flow"
            }

    # --- 4. Update historical record ---
    historical_data['recent_interventions'].append(intervention)
    # Keep only last 10 entries
    if len(historical_data['recent_interventions']) > 10:
        historical_data['recent_interventions'].pop(0)

    return intervention
```

### Key design choices:
- **Emotional state detection** uses three real‑time metrics (typing speed, voice pitch, sentiment) to classify the student’s current state.
- **Interventions are context‑sensitive**: frustration gets a gentle alternative explanation, fatigue gets a break, flow gets a spaced‑recall insertion, neutral gets mirroring.
- **Avoids over‑intervention** by checking the time since the last intervention.
- **Spaced‑recall anchoring is emotion‑gated**: the system only inserts a review when the student is in a positive/flow state to maximize retention without causing frustration.
- **Payloads** include both a visible message (for emotional anchoring) and an action for the tutor engine to execute.

